"""CSV Insights — dependency-free CLI analytics tool.

Parse RFC-4180-style CSV files, filter rows, and compute grouped
aggregations (sum / avg) using exact decimal arithmetic.
"""

from __future__ import annotations

import argparse
import csv
import json
import sys
from decimal import Decimal, InvalidOperation
from pathlib import Path
from typing import Dict, List, Optional, Sequence, Tuple


class CsvInsightsError(Exception):
    """Base class for all user-facing errors."""


class ParseError(CsvInsightsError):
    """Raised when the CSV file itself is malformed."""


class ValidationError(CsvInsightsError):
    """Raised when input data does not satisfy constraints."""


class ArgumentError(CsvInsightsError):
    """Raised when command-line arguments are invalid."""


def _format_decimal(value: Decimal) -> str:
    """Return a plain, minimal decimal string (e.g. '3', '2.5', '0.01')."""
    formatted = format(value, 'f')
    return formatted


def _parse_csv(path: Path) -> Tuple[List[str], List[List[str]]]:
    """Parse an RFC-4180-style CSV file.

    Returns (headers, rows) where each row is a list of strings.
    Raises ParseError on empty headers, duplicate headers, or rows with
    a wrong field count.
    """
    try:
        raw_text = path.read_text(encoding='utf-8', newline='')
    except OSError as exc:
        raise ParseError(f"cannot read '{path}': {exc}") from exc

    if not raw_text.strip():
        raise ParseError(f"file '{path}' is empty")

    reader = csv.reader(raw_text.splitlines(keepends=True))
    rows: List[List[str]] = list(reader)

    if not rows:
        raise ParseError(f"file '{path}' has no rows")

    headers = [cell.strip('"') if False else cell for cell in rows[0]]
    # Actually, csv.reader already handles quoting; just take raw values.
    headers = rows[0]

    if not any(headers):
        raise ParseError("headers are empty")

    seen: Dict[str, int] = {}
    for idx, h in enumerate(headers):
        if h in seen:
            raise ParseError(
                f"duplicate header '{h}' at column {seen[h]} and {idx}"
            )
        seen[h] = idx

    data_rows = rows[1:]
    for i, row in enumerate(data_rows, start=2):
        if len(row) != len(headers):
            raise ParseError(
                f"row {i} has {len(row)} fields, expected {len(headers)}"
            )

    return headers, data_rows


def _parse_where_filter(spec: str, headers: Sequence[str]) -> Tuple[str, str]:
    """Parse a single --where COLUMN=VALUE spec into (column, value).

    The value part may itself contain '=' signs.  An empty column or
    missing '=' is an ArgumentError.
    """
    if '=' not in spec:
        raise ArgumentError(
            f"invalid --where filter '{spec}': expected COLUMN=VALUE"
        )
    column, value = spec.split('=', 1)
    if not column:
        raise ArgumentError(
            f"invalid --where filter '{spec}': empty column name"
        )
    if column not in headers:
        raise ArgumentError(
            f"unknown column '{column}' in --where filter; "
            f"available columns: {', '.join(headers)}"
        )
    return column, value


def _apply_filters(
    headers: Sequence[str],
    rows: List[List[str]],
    filters: Sequence[Tuple[str, str]],
) -> List[List[str]]:
    """Return only rows matching all (column, value) filters (exact string)."""
    col_index = {h: i for i, h in enumerate(headers)}
    out: List[List[str]] = []
    for row in rows:
        if all(row[col_index[col]] == val for col, val in filters):
            out.append(row)
    return out


def _to_decimal(cell: str, row_num: int, column: str) -> Decimal:
    """Convert a cell to Decimal, raising ValidationError on blank/invalid."""
    if cell.strip() == '':
        raise ValidationError(
            f"row {row_num}, column '{column}': blank value cannot be "
            f"converted to a number"
        )
    try:
        return Decimal(cell.strip())
    except InvalidOperation as exc:
        raise ValidationError(
            f"row {row_num}, column '{column}': value '{cell}' is not a "
            f"valid number"
        ) from exc


def _aggregate(
    headers: Sequence[str],
    rows: List[List[str]],
    group_by: str,
    sum_col: Optional[str],
    avg_col: Optional[str],
) -> List[Dict[str, str]]:
    """Group rows by *group_by* and compute sum/avg as requested.

    Returns a list of dict rows sorted lexicographically by group value,
    with keys named group_by, sum_<col>, avg_<col>.
    """
    if group_by not in headers:
        raise ArgumentError(
            f"unknown group-by column '{group_by}'; "
            f"available columns: {', '.join(headers)}"
        )

    for col in (sum_col, avg_col):
        if col is not None and col not in headers:
            raise ArgumentError(
                f"unknown aggregation column '{col}'; "
                f"available columns: {', '.join(headers)}"
            )

    gi = headers.index(group_by)

    groups: Dict[str, List[List[str]]] = {}
    for i, row in enumerate(rows, start=2):
        key = row[gi]
        groups.setdefault(key, []).append(row)

    result: List[Dict[str, str]] = []
    for key in sorted(groups.keys()):
        entry: Dict[str, str] = {group_by: key}

        if sum_col is not None:
            si = headers.index(sum_col)
            total = Decimal('0')
            for i, row in enumerate(groups[key], start=2):
                total += _to_decimal(row[si], _row_num(key, i), sum_col)
            entry[f'sum_{sum_col}'] = _format_decimal(total)

        if avg_col is not None:
            ai = headers.index(avg_col)
            total = Decimal('0')
            group_rows = groups[key]
            for i, row in enumerate(group_rows, start=2):
                total += _to_decimal(row[ai], _row_num(key, i), avg_col)
            count = Decimal(len(group_rows))
            entry[f'avg_{avg_col}'] = _format_decimal(total / count)

        result.append(entry)

    return result


def _row_num(key: str, i: int) -> int:
    """Helper for error reporting — returns a pseudo row number."""
    return i


def _emit_json(rows: List[Dict[str, object]]) -> str:
    return json.dumps(rows, indent=2, ensure_ascii=False) + '\n'


def _emit_csv(
    rows: List[Dict[str, object]], field_order: Sequence[str]
) -> str:
    import io
    buf = io.StringIO()
    writer = csv.DictWriter(
        buf, fieldnames=list(field_order), quoting=csv.QUOTE_MINIMAL
    )
    writer.writeheader()
    for r in rows:
        writer.writerow(r)
    return buf.getvalue()

