def _aggregate(
    headers: Sequence[str],
    rows: List[List[str]],
    group_by: str,
    sum_col: Optional[str],
    avg_col: Optional[str],
) -> List[Dict[str, str]]:
    """Group rows by *group_by* and compute sum/avg as requested.

    Returns a list of dict rows sorted lexicographically by group value,
    with keys named group_by, sum_<col>, avg_<col>.
    """
    if group_by not in headers:
        raise ArgumentError(
            f"unknown group-by column '{group_by}'; "
            f"available columns: {', '.join(headers)}"
        )

    for col in (sum_col, avg_col):
        if col is not None and col not in headers:
            raise ArgumentError(
                f"unknown aggregation column '{col}'; "
                f"available columns: {', '.join(headers)}"
            )

    gi = headers.index(group_by)

    groups: Dict[str, List[List[str]]] = {}
    for i, row in enumerate(rows, start=2):
        key = row[gi]
        groups.setdefault(key, []).append(row)

    result: List[Dict[str, str]] = []
    for key in sorted(groups.keys()):
        entry: Dict[str, str] = {group_by: key}

        if sum_col is not None:
            si = headers.index(sum_col)
            total = Decimal('0')
            for i, row in enumerate(groups[key], start=2):
                total += _to_decimal(row[si], _row_num(key, i), sum_col)
            entry[f'sum_{sum_col}'] = _format_decimal(total)

        if avg_col is not None:
            ai = headers.index(avg_col)
            total = Decimal('0')
            group_rows = groups[key]
            for i, row in enumerate(group_rows, start=2):
                total += _to_decimal(row[ai], _row_num(key, i), avg_col)
            count = Decimal(len(group_rows))
            entry[f'avg_{avg_col}'] = _format_decimal(total / count)

        result.append(entry)

    return result


def _row_num(key: str, i: int) -> int:
    """Helper for error reporting — returns a pseudo row number."""
    return i


def _emit_json(rows: List[Dict[str, object]]) -> str:
    return json.dumps(rows, indent=2, ensure_ascii=False) + '\n'


def _emit_csv(
    rows: List[Dict[str, object]], field_order: Sequence[str]
) -> str:
    import io
    buf = io.StringIO()
    writer = csv.DictWriter(
        buf, fieldnames=list(field_order), quoting=csv.QUOTE_MINIMAL
    )
    writer.writeheader()

    writer.writeheader()
    for r in rows:
        writer.writerow(r)
    return buf.getvalue()


def _build_argparser() -> argparse.ArgumentParser:
    parser = argparse.ArgumentParser(
        prog='csv-insights',
        description='Dependency-free CSV analytics CLI.',
        add_help=True,
    )
    parser.add_argument('input', help='Path to the input CSV file')
    parser.add_argument(
        '--where', action='append', default=[], metavar='COLUMN=VALUE',
        help='Filter rows where COLUMN equals VALUE (repeatable, AND logic).',
    )
    parser.add_argument('--group-by', metavar='COLUMN', help='Group by COLUMN.')
    parser.add_argument('--sum', metavar='COLUMN', help='Sum COLUMN per group.')
    parser.add_argument('--avg', metavar='COLUMN', help='Average COLUMN per group.')
    parser.add_argument(
        '--output', choices=['json', 'csv'], default='json',
        help='Output format (default: json).',
    )
    return parser


def run(argv: Optional[Sequence[str]] = None) -> int:
    """Entry point. Returns process exit code."""
    parser = _build_argparser()
    try:
        args = parser.parse_args(list(argv) if argv is not None else None)
    except argparse.ArgumentError as exc:
        print(f"error: {exc}", file=sys.stderr)
        return 2
    except SystemExit as e:
        return int(e.code) if e.code is not None else 0

    input_path = Path(args.input)

    # --- parse CSV ---
    try:
        headers, data_rows = _parse_csv(input_path)
    except ParseError as exc:
        print(f"error: {exc}", file=sys.stderr)
        return 1

    # --- parse where filters ---
    filters: List[Tuple[str, str]] = []
    for spec in args.where:
        try:
            col, val = _parse_where_filter(spec, headers)
        except ArgumentError as exc:
            print(f"error: {exc}", file=sys.stderr)
            return 1
        filters.append((col, val))

    # --- validate aggregation deps ---
    if (args.sum or args.avg) and not args.group_by:
        print(
            "error: --sum and --avg require --group-by",
            file=sys.stderr,
        )
        return 1

    # --- filter ---
    filtered = _apply_filters(headers, data_rows, filters)

    # --- aggregate or passthrough ---
    if args.group_by:
        try:
            result = _aggregate(
                headers, filtered, args.group_by, args.sum, args.avg,
            )
        except (ArgumentError, ValidationError) as exc:
            print(f"error: {exc}", file=sys.stderr)
            return 1

        # Determine column order for output
        if result:
            field_order: List[str] = [args.group_by]
            if args.sum:
                field_order.append(f'sum_{args.sum}')
            if args.avg:
                field_order.append(f'avg_{args.avg}')
        else:
            field_order = [args.group_by]
            if args.sum:
                field_order.append(f'sum_{args.sum}')
            if args.avg:
                field_order.append(f'avg_{args.avg}')

        if args.output == 'csv':
            sys.stdout.write(_emit_csv(result, field_order))
        else:
            # JSON — preserve field order as dict insertion order

            sys.stdout.write(_emit_json(result))
    else:
        # No aggregation: emit filtered rows
        dict_rows = [dict(zip(headers, row)) for row in filtered]
        if args.output == 'csv':
            # Re-emit with original headers
            import io
            buf = io.StringIO()
            writer = csv.DictWriter(
                buf, fieldnames=list(headers), quoting=csv.QUOTE_MINIMAL
            )
            writer.writeheader()
            for r in dict_rows:
                writer.writerow(r)
            sys.stdout.write(buf.getvalue())
        else:
            sys.stdout.write(_emit_json(dict_rows))

    return 0


def main() -> None:
    sys.exit(run())


if __name__ == '__main__':
    main()

